  '  maxTokens: 900,',
  '  reasoningEffort: "off", // 教学用：关闭 thinking，聚焦原生 tool-call',
  '})) {',
  '  if (chunk.type === "text-delta") text += chunk.text;',
  '  if (chunk.type === "tool-call-delta") collectToolCall(chunk);',
  '}',
